  1	// The first launch: the welcome, then the Printers step. Each screen is the
  2	// board of the same name on the "JusPrin v2" canvas's "On boarding
  3	// experience" page (first-run-welcome-01, first-run-04 to 08, 18 to 20). The host
  4	// decides which is in front (Home/OnboardingModel) and carries out every
  5	// door; this file only draws them.
  6	//
  7	// Every door on the welcome comes back into the sequence: signing in waits on
  8	// the offer card, Preferences closes back onto the welcome, and "Just slice
  9	// for now" moves on at once.
 10	
 11	import { useEffect, useRef, useState } from 'react';
 12	import type { Appearance, OnboardingState } from '../bridge/protocol';
 13	import { afterPaint } from '@shared/afterPaint';
 14	import { SIGNUP_AFTER, SIGNUP_OFFER, SIGNUP_SCALE, signedInCredits } from '../../../AgentUI/src/credits';
 15	import { OrcaImportResultLines, OrcaPrinterList } from '../../../AgentUI/src/components/OrcaImportLists';
 16	import clip from '@resources/jusprin/welcome/welcome-clip.mp4';
 17	import { SignInDoor as SharedSignInDoor, SignInActions } from '../../../AgentUI/src/components/SignInDoor';
 18	import { CheckGlyph, FolderGlyph } from './Glyphs';
 19	import { Lockup } from './Lockup';
 20	import { PrinterPickerHost } from './PrinterPickerHost';
 21	import type { PrinterPick } from '../../../AgentUI/src/components/PrinterPicker';
 22	
 23	// What Skip installs: OrcaSlicer's Generic Klipper Printer, its 250 × 250 mm
 24	// bed and Klipper G-code (OrcaHomeBackend::assume_default_printer). Home's
 25	// "No printer yet" card and its drop zone say the same.
 26	export const STAND_IN_PRINTER = 'Until you add yours, files are sliced for a 250 mm Klipper printer and may not print on other printers.';
 27	// The same before Skip, under Continue and Skip for now.
 28	const SKIP_PRINTER = 'If you skip, files are sliced for a stand-in printer with a 250 mm bed, not for yours. Add your printer before you '
 29	  + 'print anything. You can do that later on the home screen.';
 30	
 31	// How long the card says who signed in before the Printers step.
 32	const SIGNED_IN_PAUSE_MS = 1500;
 33	
 34	type Action = (type: string, payload?: object) => void;
 35	
 36	// Home's own buttons, drawn in the shared sign-in.
 37	const HOME_BUTTONS = { primary: 'button-primary', secondary: 'button-secondary' };
 38	
 39	interface Props {
 40	  onboarding: OnboardingState;
 41	  appearance: Appearance;
 42	  error?: string;
 43	  onAction: Action;
 44	}
 45	
 46	// Who signed in, under what signing in got them: the free credits a new
 47	// account was just given, or what an account used before has left.
 48	function SignedIn({ onboarding }: { onboarding: OnboardingState }) {
 49	  const account = onboarding.account;
 50	  if (!account) return <p className="onboarding-door-title" role="status">Signed in as {onboarding.accountEmail}</p>;
 51	  return (
 52	    <div role="status">
 53	      <p className="onboarding-door-title">{signedInCredits(account)}</p>
 54	      <p className="onboarding-door-detail">Signed in as {onboarding.accountEmail}</p>
 55	    </div>
 56	  );
 57	}
 58	
 59	// The first door, on the welcome and in Home's AI group alike: the sign-up
 60	// offer over the JusPrin sign-in every screen shares (AgentUI's SignInDoor),
 61	// and who signed in. Returns the words and controls only; the caller frames
 62	// them.
 63	export function SignInDoor({ onboarding, onAction, offer }: { onboarding: OnboardingState; onAction: Action; offer?: boolean }) {
 64	  if (onboarding.signIn === 'idle' && onboarding.accountEmail) return <SignedIn onboarding={onboarding} />;
 65	  const actions: SignInActions = {
 66	    google: () => onAction('onboarding_sign_in'),
 67	    email: (address) => onAction('onboarding_sign_in_email', { email: address }),
 68	    sendCode: () => onAction('onboarding_sign_in_send_code'),
 69	    code: (code) => onAction('onboarding_sign_in_code', { code }),
 70	    password: (password) => onAction('onboarding_sign_in_password', { password }),
 71	    cancel: () => onAction('onboarding_sign_in_cancel'),
 72	    reopen: () => onAction('onboarding_sign_in_reopen'),
 73	    openLink: (link) => onAction('onboarding_open_link', { link }),
 74	    getNewVersion: () => onAction('check_for_updates'),
 75	  };
 76	  return (
 77	    <SharedSignInDoor phase={onboarding.signIn} email={onboarding.email} error={onboarding.signInError}
 78	      outdated={onboarding.signInOutdated} actions={actions} buttons={HOME_BUTTONS}>
 79	      {offer && <p className="onboarding-door-title">{SIGNUP_OFFER}</p>}
 80	      {offer && <p className="onboarding-door-detail">{SIGNUP_SCALE}</p>}
 81	      {offer && (
 82	        <p className="onboarding-door-detail">
 83	          {SIGNUP_AFTER}{' '}
 84	          {/* The server's Credits and plans, in the app's sheet. */}
 85	          <button type="button" className="sign-in-link inline" onClick={() => onAction('onboarding_see_prices')}>See prices</button>
 86	        </p>
 87	      )}
 88	    </SharedSignInDoor>
 89	  );
 90	}
 91	
 92	// The agent on the person's own AI account, an API key or Claude Code and
 93	// Claude Desktop: Preferences › Agent explains both, and closes back here.
 94	// A card of its own under the offer, with what it costs.
 95	export function OwnAccountDoor({ onAction, disabled }: { onAction: Action; disabled: boolean }) {
 96	  return (
 97	    <button type="button" className="onboarding-door" disabled={disabled}
 98	      onClick={() => onAction('onboarding_open_preferences', { door: 'key' })}>
 99	      <span className="onboarding-door-text">
100	        <span className="onboarding-door-name">Use your own AI account</span>
101	        <span className="onboarding-door-what">Your API key, or Claude Code or Claude Desktop</span>
102	      </span>
103	      <span className="onboarding-door-cost">Free</span>
104	    </button>
105	  );
106	}
107	
108	function Welcome({ onboarding, appearance, onAction }: Props) {
109	  const signingIn = onboarding.signIn !== 'idle';
110	  // The other doors stay open while the person signs in, as canvas boards
111	  // first-run-04 and 12 to 16 draw them, and close only while the account is read.
112	  const checking = onboarding.signIn === 'checking';
113	  // Only a sign-in finished here moves on by itself. Someone who comes Back
114	  // already signed in sees who, and goes on with Continue.
115	  const waited = useRef(false);
116	  if (signingIn) waited.current = true;
117	  const signedIn = Boolean(onboarding.accountEmail) && !signingIn;
118	  useEffect(() => {
119	    if (!signedIn || !waited.current) return;
120	    const timer = setTimeout(() => onAction('onboarding_leave_welcome'), SIGNED_IN_PAUSE_MS);
121	    return () => clearTimeout(timer);
122	  }, [signedIn, onAction]);
123	
124	  return (
125	    <div className="onboarding">
126	      <Lockup appearance={appearance} className="onboarding-lockup" />
127	      <div className="onboarding-welcome">
128	        <figure className="onboarding-clip">
129	          <video src={clip} autoPlay loop muted playsInline aria-label="AI fixing a print that came out stringy" />
130	          <details className="onboarding-credits">
131	            <summary>Photo credits</summary>
132	            <p>
133	              “Dual extrusion 3D printed #3DBenchy v01” by #3DBenchy, flickr.com/photos/3dbenchy/19273965123, CC BY 2.0
134	              (creativecommons.org/licenses/by/2.0). Cropped.
135	            </p>
136	            <p>
137	              “Dual-print multi-part color 3D print of #3DBenchy v13” by #3DBenchy, flickr.com/photos/3dbenchy/19239738473,
138	              CC BY 2.0 (creativecommons.org/licenses/by/2.0). Cropped and resized.
139	            </p>
140	          </details>
141	        </figure>
142	        <div className="onboarding-pitch">
143	          <div className="onboarding-heading">
144	            <h1>The AI slicer that helps you get better prints.</h1>
145	            <p className="onboarding-lead">
146	              Show it a photo of what went wrong. AI reads your file, your settings and your slice, changes the settings
147	              and slices again.
148	            </p>
149	          </div>
150	          {/* Once signed in there is nothing left to choose: only the credits
151	              card, with Continue, stays. */}
152	          <div className="onboarding-doors">
153	            {!signedIn && <p className="onboarding-doors-label">Sign up to use AI, or skip it and just slice.</p>}
154	            <div className="onboarding-offer">
155	              <SignInDoor onboarding={onboarding} onAction={onAction} offer />
156	              {signedIn && !waited.current && (
157	                <button type="button" className="button-primary onboarding-door-button"
158	                  onClick={() => onAction('onboarding_leave_welcome')}>
159	                  Continue
160	                </button>
161	              )}
162	            </div>
163	            {!signedIn && (
164	              <>
165	                <OwnAccountDoor onAction={onAction} disabled={checking} />
166	                <button type="button" className="onboarding-link flush" disabled={checking}
167	                  onClick={() => onAction('onboarding_leave_welcome')}>
168	                  Just slice for now
169	                </button>
170	              </>
171	            )}
172	          </div>
173	        </div>
174	      </div>
175	    </div>
176	  );
177	}
178	
179	// What the welcome finished, above the first printer screen's headline:
180	// who signed in, or whose key the agent uses. Nothing after "Just slice for
181	// now".
182	function WelcomeDone({ onboarding }: { onboarding: OnboardingState }) {
183	  const { account, accountEmail } = onboarding;
184	  if (accountEmail && account) {
185	    return (
186	      <div className="onboarding-done">
187	        <CheckGlyph />
188	        <span className="onboarding-done-text">
189	          <span>{signedInCredits(account)}</span>
190	          <span className="onboarding-done-detail">Signed in as {accountEmail}</span>
191	        </span>
192	      </div>
193	    );
194	  }
195	  const text = accountEmail ? `Signed in as ${accountEmail}`
196	    : onboarding.agentKeyProvider ? `AI uses your ${onboarding.agentKeyProvider} key` : '';
197	  if (!text) return null;
198	  return <p className="onboarding-done"><CheckGlyph />{text}</p>;
199	}
200	
201	// Importing holds the app on the action's message, so the button says so
202	// first and the message goes once that has been painted. The host answers
203	// every action with fresh state.
204	function useBusy(onAction: Action, onboarding: OnboardingState) {
205	  const [busy, setBusy] = useState(false);
206	  useEffect(() => setBusy(false), [onboarding]);
207	  const run = (type: string, payload?: object) => {
208	    setBusy(true);
209	    afterPaint(() => onAction(type, payload));
210	  };
211	  return [busy, run] as const;
212	}
213	
214	// The apps the Printers step imports from, by the host's id.
215	const IMPORT_APPS = { jusprin1: 'JusPrin 1', orcaslicer: 'OrcaSlicer' } as const;
216	type Way = keyof typeof IMPORT_APPS | 'printer';
217	
218	// The other two of the three ways to set up printers, under every printer
219	// screen. The host opens the way's screen, or first asks for the app's
220	// folder when it found none.
221	function OtherWays({ ways, disabled, onAction }: { ways: Way[]; disabled?: boolean; onAction: Action }) {
222	  return (
223	    <div className="onboarding-ways">
224	      <span className="onboarding-ways-label">Other ways:</span>
225	      {ways.map((way) => (
226	        <button key={way} type="button" className="onboarding-link" disabled={disabled}
227	          onClick={() => onAction('onboarding_way', { way })}>
228	          {way === 'printer' ? 'Choose my printer' : `Import from ${IMPORT_APPS[way]}…`}
229	        </button>
230	      ))}
231	    </div>
232	  );
233	}
234	
235	// Why the last way's folder did not open its screen.
236	function WayProblem({ onboarding }: { onboarding: OnboardingState }) {
237	  return onboarding.wayProblem ? <p className="onboarding-error" role="alert">{onboarding.wayProblem}</p> : null;
238	}
239	
240	const countOf = (count: number, one: string, many: string) => `${count} ${count === 1 ? one : many}`;
241	
242	// Bring the printers of JusPrin 1 (first-run-19) or OrcaSlicer (first-run-07).
243	function PrinterImport({ onboarding, error, onAction }: Props) {
244	  const found = onboarding.printerImport;
245	  const id = found.app === 'jusprin1' ? 'jusprin1' : 'orcaslicer';
246	  const app = IMPORT_APPS[id];
247	  const [busy, run] = useBusy(onAction, onboarding);
248	  // Every printer starts ticked; only the ticked ones are imported.
249	  const [chosen, setChosen] = useState(found.printers);
250	  const listed = found.printers.join('\n');
251	  useEffect(() => setChosen(found.printers), [listed]);
252	  const choose = (name: string, ticked: boolean) =>
253	    setChosen((now) => (ticked ? [...now, name] : now.filter((one) => one !== name)));
254	  const brings = [found.filamentCount > 0 && countOf(found.filamentCount, 'filament', 'filaments'),
255	    found.settingsCount > 0 && countOf(found.settingsCount, 'print setting', 'print settings')].filter(Boolean).join(' and ');
256	  return (
257	    <div className="onboarding-step">
258	      <WelcomeDone onboarding={onboarding} />
259	      <div className="onboarding-heading">
260	        <h1>Bring your printers from {app}?</h1>
261	        <p className="onboarding-lead">
262	          JusPrin copies these printers with their filaments and print settings. {app} keeps its own copy.
263	        </p>
264	      </div>
265	      <OrcaPrinterList app={app} printers={found.printers.map((name) => ({ name, already: false }))} chosen={chosen}
266	        onChoose={choose} disabled={busy} />
267	      <div className="onboarding-source">
268	        {brings && <p>Also brings {brings}.</p>}
269	        <p className="onboarding-source-folder">
270	          <FolderGlyph />
271	          <span className="onboarding-source-path">{app} keeps these in {found.source}</span>
272	        </p>
273	      </div>
274	      {error && <p className="onboarding-error" role="alert">{error}</p>}
275	      <div className="onboarding-actions">
276	        <button type="button" className="button-primary" disabled={busy || chosen.length === 0}
277	          onClick={() => run('onboarding_import', { app: id, printers: chosen })}>
278	          {busy ? 'Importing…' : 'Import'}
279	        </button>
280	      </div>
281	      <WayProblem onboarding={onboarding} />
282	      <OtherWays ways={[id === 'jusprin1' ? 'orcaslicer' : 'jusprin1', 'printer']} disabled={busy} onAction={onAction} />
283	      <button type="button" className="onboarding-link flush" disabled={busy} onClick={() => onAction('onboarding_back')}>Back</button>
284	    </div>
285	  );
286	}
287	
288	// A line not imported says what to do about it, trying again included.
289	function ImportResult({ onboarding, error, onAction }: Props) {
290	  const items = onboarding.printerImport.result ?? [];
291	  const app = IMPORT_APPS[onboarding.printerImport.app === 'jusprin1' ? 'jusprin1' : 'orcaslicer'];
292	  return (
293	    <div className="onboarding-step">
294	      <div className="onboarding-heading">
295	        <h1>Imported from {app}</h1>
296	      </div>
297	      <OrcaImportResultLines app={app} lines={items} />
298	      {error && <p className="onboarding-error" role="alert">{error}</p>}
299	      <div className="onboarding-actions">
300	        <button type="button" className="button-primary" onClick={() => onAction('onboarding_import_continue')}>
301	          Continue
302	        </button>
303	      </div>
304	    </div>
305	  );
306	}
307	
308	// "Which printer do you have?": the printer and its nozzle, added with its
309	// profile's own plate and filament. The dialog Home's "+ Add printer" opens
310	// asks for those too.
311	function ChoosePrinter({ onboarding, error, onAction }: Props) {
312	  const form = onboarding.printerForm;
313	  const [pick, setPick] = useState<PrinterPick>({});
314	  const { catalogId, nozzle, deviceId } = pick;
315	  // Continue waits for the app: it either leaves for Home or says why not.
316	  const [finishing, setFinishing] = useState(false);
317	  useEffect(() => { setFinishing(false); }, [form?.error]);
318	  useEffect(() => {
319	    if (catalogId && nozzle !== undefined) onAction('onboarding_printer_form', { action: 'form_options', catalogId, nozzle });
320	  }, [catalogId, nozzle]);
321	  // The options the app sent for exactly this choice, and none for another.
322	  const options = form?.options && form.options.catalogId === catalogId && form.options.nozzle === nozzle ? form.options : undefined;
323	  const ready = options !== undefined && !form?.loading && !options.error;
324	  // The agent can help only when it can answer: an account with credits, or a key.
325	  const agentReady = onboarding.agentKeyProvider !== '' ||
326	    (onboarding.accountEmail !== '' && (onboarding.account?.credits.total ?? 0) > 0);
327	
328	  const finish = () => {
329	    if (!options || !catalogId || nozzle === undefined) return;
330	    const plate = options.plates.some((entry) => entry.type === options.defaultPlate) ? options.defaultPlate : options.plates[0]?.type;
331	    setFinishing(true);
332	    onAction('onboarding_printer_form', { action: 'form_finish', catalogId, nozzle,
333	      ...(options.plates.length > 0 ? { plate } : {}), ...(deviceId ? { deviceId } : {}) });
334	  };
335	
336	  return (
337	    <div className="onboarding-step">
338	      <WelcomeDone onboarding={onboarding} />
339	      <div className="onboarding-heading">
340	        <h1>Which printer do you have?</h1>
341	        <p className="onboarding-lead">
342	          JusPrin prepares every print to fit your printer’s bed and nozzle. You can add more printers later.
343	        </p>
344	      </div>
345	      {form ? (
346	        <PrinterPickerHost form={form} pick={pick} onPick={setPick}
347	          reading={Boolean(form.loading && catalogId && nozzle !== undefined)}
348	          onAskAgent={agentReady ? () => onAction('onboarding_ask_agent') : undefined} />
349	      ) : (
350	        <p className="onboarding-lead" role="status">Reading the printer list…</p>
351	      )}
352	      {options?.error && <p className="onboarding-error" role="alert">{options.error}</p>}
353	      {form?.error && <p className="onboarding-error" role="alert">{form.error}</p>}
354	      {error && <p className="onboarding-error" role="alert">{error}</p>}
355	      <div className="onboarding-step-group">
356	        <div className="onboarding-actions">
357	          <button type="button" className="button-primary" disabled={!ready || finishing} onClick={finish}>Continue</button>
358	          <button type="button" className="onboarding-link" onClick={() => onAction('onboarding_assume_default')}>Skip for now</button>
359	        </div>
360	        {!catalogId && <p className="onboarding-note">{SKIP_PRINTER}</p>}
361	      </div>
362	      <WayProblem onboarding={onboarding} />
363	      <OtherWays ways={['jusprin1', 'orcaslicer']} onAction={onAction} />
364	      <button type="button" className="onboarding-link flush" onClick={() => onAction('onboarding_back')}>Back</button>
365	    </div>
366	  );
367	}
368	
369	export function Onboarding(props: Props) {
370	  if (props.onboarding.step === 'welcome') return <Welcome {...props} />;
371	  return (
372	    <div className="onboarding">
373	      <Lockup appearance={props.appearance} className="onboarding-lockup" />
374	      {props.onboarding.printersScreen === 'v1_import' || props.onboarding.printersScreen === 'orca_import'
375	        ? <PrinterImport {...props} />
376	        : props.onboarding.printersScreen === 'import_result' ? <ImportResult {...props} />
377	          : <ChoosePrinter {...props} />}
378	    </div>
379	  );
380	}

