# Serves the instrumented Home page, logs what it reports, saves page snapshots.
import http.server, sys, os, urllib.parse, time
root, port = sys.argv[1], int(sys.argv[2])
os.chdir(root)
class H(http.server.SimpleHTTPRequestHandler):
    def log_message(self, *a): pass
    def end_headers(self):
        self.send_header('Access-Control-Allow-Origin', '*'); super().end_headers()
    def do_OPTIONS(self):
        self.send_response(204); self.send_header('Access-Control-Allow-Headers', '*'); self.end_headers()
    def do_GET(self):
        u = urllib.parse.urlparse(self.path)
        if u.path == '/log':
            with open('log.txt', 'a') as f: f.write(time.strftime('%H:%M:%S ') + urllib.parse.unquote(u.query) + '\n')
            self.send_response(204); self.end_headers(); return
        return super().do_GET()
    def do_POST(self):
        u = urllib.parse.urlparse(self.path)
        name = urllib.parse.parse_qs(u.query)['name'][0]
        body = self.rfile.read(int(self.headers['Content-Length']))
        os.makedirs('snaps', exist_ok=True)
        open(os.path.join('snaps', name + '.html'), 'wb').write(body)
        self.send_response(204); self.end_headers()
http.server.ThreadingHTTPServer(('127.0.0.1', port), H).serve_forever()
